const f=(key,label,value,unit='',max)=>({key,label,value,unit,max});
const div=(a,b)=>b>0?a/b:null;
export const calculators=[
{id:'leads',name:'Lead Generation',category:'Growth',icon:'↗',description:'Turn your outreach into a clear revenue forecast.',fields:[f('p','Prospects contacted',1000),f('r','Response rate',10,'%',100),f('c','Response-to-call rate',40,'%',100),f('q','Call-to-proposal rate',50,'%',100),f('w','Proposal closing rate',25,'%',100),f('v','Average client value',3000,'$'),f('t','Revenue target',15000,'$')],calculate:x=>{let a=x.p*x.r/100,b=a*x.c/100,c=b*x.q/100,d=c*x.w/100;return [['Expected responses',a],['Expected calls',b],['Expected proposals',c],['Expected customers',d],['Estimated contracted revenue',d*x.v,'$'],['Prospects needed for target',div(x.t,x.r/100*x.c/100*x.q/100*x.w/100*x.v),'ceil']];},formula:'Each stage = previous stage × conversion rate. Revenue = customers × client value. Required prospects = target ÷ revenue per prospect. Fractional funnel results are expected values, not guaranteed customers.'},
{id:'profit',name:'Client Profit Improvement',category:'Profitability',icon:'◈',description:'Measure the value of better conversion and lower costs.',fields:[f('l','Monthly qualified leads',100),f('c','Current closing rate',20,'%',100),f('t','Target closing rate',30,'%',100),f('v','Average transaction value',1000,'$'),f('m','Contribution margin',60,'%',100),f('s','Monthly cost savings',500,'$')],calculate:x=>{let a=x.l*(x.t-x.c)/100,b=a*x.v,c=b*x.m/100;return [['Additional customers',a],['Additional revenue',b,'$'],['Incremental contribution',c,'$'],['Monthly financial benefit',c+x.s,'$'],['Annualized financial benefit',(c+x.s)*12,'$'],['Closing rate change',x.t-x.c,'pp']];},formula:'Additional customers = leads × (target − current closing rate). Contribution = additional revenue × contribution margin. Benefit = contribution + cash savings. Annual benefit assumes 12 identical months.'},
{id:'pricing',name:'Consulting Pricing',category:'Profitability',icon:'⌁',description:'Price your expertise with your delivery costs in view.',fields:[f('h','Estimated project hours',40,'hours'),f('l','Founder labor cost per hour',75,'$'),f('c','Contractor costs',1000,'$'),f('s','Software expenses',200,'$'),f('o','Other project costs',100,'$'),f('b','Contingency',10,'%',100),f('m','Target contribution margin',50,'%',100),f('p','Proposed fee',10000,'$')],calculate:x=>{let c=(x.h*x.l+x.c+x.s+x.o)*(1+x.b/100),p=x.p-c;return [['Estimated delivery cost',c,'$'],['Minimum price for target margin',div(c,1-x.m/100),'$'],['Proposed fee contribution',p,'$'],['Proposed fee margin',div(p*100,x.p),'%'],['Contribution per founder hour',div(p,x.h),'$']];},formula:'Delivery cost = (founder labor + contractors + software + other costs) × (1 + contingency). Minimum price = cost ÷ (1 − target margin). Contribution here includes the modeled founder labor cost; it is before taxes. A 100% target margin is infeasible.'},
{id:'launch',name:'Business Launch Service',category:'Operations',icon:'◇',description:'Explore the economics of your next service package.',fields:[f('p','Service package price',999,'$'),f('n','Monthly clients',4),f('h','Hours per client',8,'hours'),f('d','Direct expenses per client',100,'$'),f('a','Acquisition cost per client',75,'$'),f('f','Monthly fixed expenses',400,'$')],calculate:x=>{let r=x.p*x.n,d=(x.d+x.a)*x.n,c=r-d,h=x.h*x.n;return [['Monthly revenue',r,'$'],['Monthly cash expenses',d+x.f,'$'],['Estimated contribution',c,'$'],['Operating profit before owner pay & taxes',c-x.f,'$'],['Founder hours required',h,'hours'],['Contribution per founder hour',div(c,h),'$']];},formula:'Revenue = price × clients. Variable cash costs = clients × (direct expenses + acquisition cost). Contribution = revenue − variable cash costs. Operating profit subtracts fixed expenses and excludes owner compensation and taxes.'},
{id:'revenue',name:'Revenue Goal',category:'Growth',icon:'◎',description:'Work backward from your goal to your weekly outreach.',fields:[f('t','Monthly target revenue',15000,'$'),f('p','Average engagement price',3000,'$'),f('c','Discovery call closing rate',25,'%',100),f('d','Prospect-to-discovery-call rate',5,'%',100),f('h','Available weekly outreach hours',10,'hours'),f('s','Outreach minutes per prospect',5,'minutes')],calculate:x=>{let n=div(x.t,x.p),c=n===null?null:div(Math.ceil(n),x.c/100),p=c===null?null:div(Math.ceil(c),x.d/100),h=p===null?null:Math.ceil(p)*x.s/60;return [['Required customers',n,'ceil'],['Required discovery calls',c,'ceil'],['Required prospects',p,'ceil'],['Estimated monthly outreach workload',h,'hours'],['Available monthly outreach hours',x.h*52/12,'hours'],['Outreach hours remaining',h===null?null:x.h*52/12-h,'hours']];},formula:'Round customers, calls, and prospects up at each stage. Calls = customers ÷ closing rate; prospects = calls ÷ prospect-to-call rate. Workload = prospects × minutes per prospect ÷ 60. Additional editable assumption: minutes per prospect includes follow-up; 52/12 weeks per month.'},
{id:'capacity',name:'Workload & Capacity',category:'Operations',icon:'▥',description:'Find room to grow without overloading your week.',fields:[f('h','Available working hours',40,'hours'),f('c','Delivery hours per client',5,'hours'),f('n','Current active customers',4),f('a','Administrative hours',6,'hours'),f('p','Prospecting hours',8,'hours')],calculate:x=>{let a=Math.max(0,x.h-x.a-x.p),m=div(a,x.c);return [['Available delivery hours',a,'hours'],['Maximum sustainable clients',m===null?null:Math.floor(m)],['Estimated delivery utilization',div(x.n*x.c*100,a),'%'],['Remaining client capacity',m===null?null:Math.floor(m)-x.n],['Remaining delivery hours',a-x.n*x.c,'hours']];},formula:'Delivery hours = max(0, working − administration − prospecting). Capacity = floor(delivery hours ÷ hours per client). Utilization = committed delivery hours ÷ available delivery hours. All hours refer to the selected period; monthly view converts hours using 52/12.'},
{id:'roi',name:'Client ROI',category:'Profitability',icon:'↺',description:'Estimate the return on a consulting investment.',fields:[f('f','Consulting fee',5000,'$'),f('s','Upfront software expenses',500,'$'),f('o','Other implementation expenses',500,'$'),f('c','Incremental monthly contribution',2000,'$'),f('v','Verified monthly cash savings',500,'$'),f('r','Ramp-up period with no benefit',2,'months'),f('e','Evaluation period',12,'months')],calculate:x=>{let i=x.f+x.s+x.o,b=x.c+x.v,total=Math.max(0,x.e-x.r)*b;return [['Total client investment',i,'$'],['Monthly net benefit after ramp-up',b,'$'],['Cumulative financial benefit',total,'$'],['Net ROI',div((total-i)*100,i),'%'],['Break-even from project start',i===0?0:b>0?x.r+i/b:null,'months'],['12-month ROI scenario',div((Math.max(0,12-x.r)*b-i)*100,i),'%']];},formula:'Investment = fee + upfront software + implementation expenses. Monthly benefit = incremental contribution + verified cash savings (net of ongoing costs). No benefits during ramp-up. Cumulative benefit = benefit × max(0, evaluation − ramp-up). ROI = (benefit − investment) ÷ investment. Break-even assumes benefits continue. The annual scenario uses the first 12 months, not compounded returns.'},
{id:'cash',name:'Cash Flow',category:'Operations',icon:'≋',description:'See when cash arrives and what stays in the bank.',fields:[f('v','Total contracts signed',20000,'$'),f('p','First payment percentage',50,'%',100),f('q','Second payment percentage',50,'%',100),f('e','Monthly cash expenses',4000,'$'),f('s','Starting cash balance',3000,'$'),f('i','Other monthly cash inflows',0,'$'),f('o','Other monthly cash outflows',0,'$')],calculate:x=>{let balance=x.s,rows=[];for(let m=0;m<6;m++){let date=new Date(x.start+'-01T12:00:00');date.setMonth(date.getMonth()+m);let key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`,collections=(x.first.slice(0,7)===key?x.v*x.p/100:0)+(x.second.slice(0,7)===key?x.v*x.q/100:0),net=collections+x.i-x.e-x.o;balance+=net;rows.push({month:date.toLocaleDateString('en-US',{month:'short',year:'numeric'}),collections,net,balance});}return [['Contract value (not collected cash)',x.v,'$'],['Scheduled cash collections',x.v*(x.p+x.q)/100,'$'],['Ending cash after six months',balance,'$'],['Lowest month-end cash',Math.min(...rows.map(r=>r.balance)),'$'],...rows.flatMap(r=>[[r.month+' cash collections',r.collections,'$'],[r.month+' operating cash flow',r.net,'$'],[r.month+' ending cash',r.balance,'$']])];},formula:'Two payments share the total signed contract value. Collections are included only in their expected collection month. Monthly operating cash flow = collections + other inflows − expenses − other outflows. Ending cash = prior cash + cash flow. Recurring amounts repeat for six months. Payments outside the window are excluded. Percentages must total no more than 100%; unallocated value remains uncollected.'}
];
export function defaults(c){return Object.fromEntries([...c.fields.map(f=>[f.key,f.value]),['start','2026-10'],['first','2026-10-20'],['second','2026-11-20'],['period','weekly']]);}
